head.script:
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'grid1_column3').innerText == '0'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.arr = [];
    arr.push(1856.2);
    arr.push(1036546.25);
    arr.push(-1095872);
    arr.push(57469.55);
    arr.push(0);
    arr.push(50912.6);
    arr.push(201.2);
    arr.push(440);
    arr.push(5.9);
    arr.push(10);
    arr.push(2025.71);
    arr.push(5249.5);
    arr.push(547.9);
    arr.push(45.5);
    arr.push(660.59);
    arr.push(-2629.35);
    arr.push(-57469.55);
    window.b = 0;
    for (var i = 0; i < arr.length; i++) {
        b += arr[i];
    }
    window.c = 0;
    for (var i = 0; i < arr.length; i++) {
        c += arr[i] * 100;
    }
    output1.setValue(b);
    output2.setValue(c / 100);
    grid1.setData(arr)
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
